 "content": "def transform(grid):
    """Annotate repeated n-by-n motifs by their macro tile coordinates.

    A solid 3-colored tile band is a masked row/column: replace it with a
    motif exactly where the motif has a 2 at the matching local coordinate.
    """
    h, w = len(grid), len(grid[0])
    n = round((5 + 4 * h) ** 0.5 - 1) / 2
    n = int(n)
    if n * (n + 1) - 1 != h or w != h:
        raise ValueError('expected square tiled grid')
    out = [row[:] for row in grid]

    # Macro tile index i has its n-cell tile at offset i*(n+1).
    starts = [i * (n + 1) for i in range(n)]
    panel_row = next((i for i, r0 in enumerate(starts)
                      if all(grid[r0 + dr][c] == 3
                             for dr in range(n) for c in range(w))), None)
    panel_col = next((j for j, c0 in enumerate(starts)
                      if all(grid[r][c0 + dc] == 3
                             for r in range(h) for dc in range(n))), None)
    if panel_row is None and panel_col is None:
        raise ValueError('no solid 3-colored panel')

    # All repeated tiles share one motif; take the first non-panel tile.
    motif = None
    for i, r0 in enumerate(starts):
        for j, c0 in enumerate(starts):
            if i == panel_row or j == panel_col:
                continue
            tile = [[grid[r0 + dr][c0 + dc] for dc in range(n)]
                    for dr in range(n)]
            if any(v == 2 for row in tile for v in row):
                motif = tile
                break
        if motif is not None:
            break
    if motif is None:
        raise ValueError('no motif found')

    for i, r0 in enumerate(starts):
        for j, c0 in enumerate(starts):
            is_panel = (i == panel_row) if panel_row is not None else (j == panel_col)
            if is_panel:
                tile = [[0] * n for _ in range(n)]
                if motif[i][j] == 2:
                    tile = [row[:] for row in motif]
                    tile[i][j] = 8
                for dr in range(n):
                    for dc in range(n):
                        out[r0 + dr][c0 + dc] = tile[dr][dc]
            elif grid[r0 + i][c0 + j] == 2:
                out[r0 + i][c0 + j] = 8
    return out
